pub fn SearchResult(comptime limit: usize) type {
    return struct {
        matches: [limit]*const Entry = undefined,
        len: usize = 0,

        pub fn items(self: *const @This()) []const *const Entry {
            return self.matches[0..self.len];
        }
    };
}

/// Searches code, locality, province, and region case-insensitively. Results
/// retain source order and distinct locality identities sharing a ZIP code,
/// while suppressing byte-identical upstream rows from the suggestion list.
pub fn search(comptime limit: usize, query: []const u8) SearchResult(limit) {
    const needle = std.mem.trim(u8, query, " \t\r\n");
    var result = SearchResult(limit){};
    for (&entries) |*entry| {
        if (!containsAsciiInsensitive(entry.code, needle) and
            !containsAsciiInsensitive(entry.locality, needle) and
            !containsAsciiInsensitive(entry.province, needle) and
            !containsAsciiInsensitive(entry.region, needle)) continue;
        var already_present = false;
        for (result.items()) |match| {
            if (sameEntry(match, entry)) {
                already_present = true;
                break;
            }
        }
        if (already_present) continue;
        if (result.len == limit) break;
        result.matches[result.len] = entry;
        result.len += 1;
    }
    return result;
}

/// Looks up snapshot membership. This is not an authoritative ZIP validator:
/// the profile contract accepts any well-formed four-digit typed code.
pub fn hasCode(code: []const u8) bool {
    for (&entries) |*entry| {
        if (std.mem.eql(u8, entry.code, code)) return true;
    }
    return false;
}

fn sameEntry(left: *const Entry, right: *const Entry) bool {
    return std.mem.eql(u8, left.code, right.code) and
        std.mem.eql(u8, left.locality, right.locality) and
        std.mem.eql(u8, left.province, right.province) and
        std.mem.eql(u8, left.region, right.region);
}

fn containsAsciiInsensitive(candidate: []const u8, query: []const u8) bool {
    if (query.len == 0) return true;
    if (query.len > candidate.len) return false;
    var start: usize = 0;
    while (start + query.len <= candidate.len) : (start += 1) {
        if (std.ascii.eqlIgnoreCase(candidate[start .. start + query.len], query)) return true;
    }
    return false;
}

test "PHLPost snapshot retains its validated rows and an initial list" {
    try std.testing.expectEqual(valid_row_count, entries.len);
    const initial = search(5, "");
    try std.testing.expectEqual(@as(usize, 5), initial.len);
    try std.testing.expectEqualStrings("1011", initial.items()[0].code);
}

test "postal search matches ZIP and geographic terms" {
    const by_code = search(5, "2600");
    try std.testing.expectEqual(@as(usize, 1), by_code.len);
    try std.testing.expectEqualStrings("Baguio City", by_code.items()[0].locality);

    const by_location = search(5, "bAgUiO");
    try std.testing.expectEqual(@as(usize, 2), by_location.len);
    try std.testing.expectEqualStrings("Baguio City", by_location.items()[0].locality);
    try std.testing.expectEqualStrings("Ambaguio", by_location.items()[1].locality);
}

test "postal catalog preserves source duplicates but suppresses exact suggestions" {
    var source_count: usize = 0;
    for (&entries) |*entry| {
        if (std.mem.eql(u8, entry.code, "9011") and
            std.mem.eql(u8, entry.locality, "Balingoan") and
            std.mem.eql(u8, entry.province, "Misamis Oriental") and
            std.mem.eql(u8, entry.region, "Region 10 (Northern Mindanao)"))
        {
            source_count += 1;
        }
    }
    try std.testing.expectEqual(@as(usize, 2), source_count);

    const suggestions = search(5, "Balingoan");
    try std.testing.expectEqual(@as(usize, 1), suggestions.len);
    try std.testing.expectEqualStrings("9011", suggestions.items()[0].code);
    try std.testing.expectEqualStrings(
        "Balingoan",
        suggestions.items()[0].locality,
    );
    try std.testing.expect(hasCode("9011"));
    try std.testing.expect(!hasCode("0000"));
}

test "postal search honors the caller cap" {
    const capped = search(1, "Region");
    try std.testing.expectEqual(@as(usize, 1), capped.len);
}
